INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (1, 'Agua_com_gas', 'Agua_com_gas', 700);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (2, 'Suco_de_abacaxi', 'Suco_de_abacaxi', 1500);
