INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (5, 'Agua_de_coco', 'Agua_de_coco', 1200);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (6, 'Suco_de_melancia', 'Suco_de_melancia', 1500);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (7, 'Gin', 'Gin', 1700);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (8, 'Uisque_de_centeio_rye', 'Uisque_de_centeio_rye', 2000);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (9, 'Pink Lemonade', 'Bebida sem álcool feita com suco de limão-siciliano, xarope de groselha ou framboesa, água com gás, gelo e suco de limão-tahiti.', 0);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (10, 'Mojito Sem Álcool', 'Bebida sem álcool preparada com folhas de hortelã, xarope simples de açúcar, água com gás e gelo.', 0);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (11, 'Piña Colada Zero', 'Bebida sem álcool feita com suco de abacaxi, leite de coco, leite condensado e gelo triturado.', 0);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (12, 'Soda Italiana de Maçã Verde', 'Bebida sem álcool preparada com xarope de maçã verde, água com gás, suco de limão e gelo.', 0);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (13, 'Coquetel de Frutas Vermelhas', 'Bebida sem álcool feita com polpa ou purê de frutas vermelhas, suco de laranja, refrigerante de guaraná ou soda e gelo.', 0);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (14, 'Iced Tea de Pêssego e Limão', 'Bebida sem álcool preparada com chá preto gelado, xarope ou suco concentrado de pêssego, suco de limão e gelo.', 0);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (15, 'Sunrise de Laranja e Grenadine', 'Bebida sem álcool feita com suco de laranja natural e xarope de grenadine ou groselha.', 0);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (16, 'Coquetel Tropical de Coco', 'Bebida sem álcool preparada com água de coco, suco de maracujá, xarope de baunilha e gelo.', 0);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (17, 'Lemonade de Extrato de Manjericão', 'Bebida sem álcool feita com suco de limão-tahiti, folhas frescas de manjericão, xarope de açúcar e água filtrada gelada.', 0);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (18, 'Refresco de Melancia e Gengibre', 'Bebida sem álcool preparada com suco de melancia fresco, suco de gengibre, açúcar e gelo picado.', 0);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (19, 'Caipirinha', 'Drink alcoólico preparado com cachaça, limão e gelo.', 0);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (20, 'Margarita', 'Drink alcoólico feito com tequila, Cointreau, suco de limão, sal e gelo.', 0);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (21, 'Negroni', 'Drink alcoólico preparado com gin, Campari, vermute tinto, gelo e casca de laranja.', 0);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (22, 'Moscow Mule', 'Drink alcoólico feito com vodka, suco de limão, ginger beer, gelo e rodela de limão.', 0);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (23, 'Cosmopolitan', 'Drink alcoólico preparado com vodka, Cointreau, suco de cranberry, suco de limão e gelo.', 0);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (24, 'Mai Tai', 'Drink alcoólico feito com rum branco, rum escuro, Cointreau, xarope de amêndoa e suco de limão.', 0);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (25, 'Old Fashioned', 'Drink alcoólico preparado com uísque bourbon, açúcar, Angostura bitters, gelo e casca de laranja.', 0);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (26, 'Manhattan', 'Drink alcoólico feito com uísque de centeio, vermute tinto, Angostura bitters, gelo e cereja marasquino.', 0);
INSERT INTO bebida (id_bebida, nome, descricao, valor_unitario) VALUES (27, 'Piña Colada', 'Drink alcoólico preparado com rum branco, suco de abacaxi, leite de coco e gelo.', 0);

